
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ge2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ge2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.393481262912179e+01, 9.028127447733024e+01, 8.528590007657709e+01, 7.860544793873441e+01, 6.995026950468582e+01, 5.923272994238126e+01, 4.678788283648210e+01, 3.359205753531925e+01, 2.127116384817436e+01, 1.158907761922901e+01, 5.331057630907363e+00, 2.537776311432535e+00, 1.906661086286335e+00, 1.264700022760251e+00, 6.460165274661610e-01, 2.672262882237828e-01, 1.163815012537548e-01, 7.623258243120420e-02, 6.724666535229225e-02, 6.381897449823161e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


